export const TOP_500_STOCKS: MarketAsset[] = TOP_500_RAW.map((s, idx) => ({
  id: s.id,
  name: s.name,
  symbol: s.symbol,
  value: s.val,
  change: s.chg,
  isPositive: s.up,
  mainCategory: 'AKTIEN',
  subclassId: s.subclassId,
  subclassName: s.sector,
  iconType: 'stock',
  sparklinePath: s.up
    ? "M 0," + (35 + (idx % 6)) + " Q 25," + (38 + (idx % 4)) + " 55," + (24 - (idx % 5)) + " T 110," + (26 - (idx % 4)) + " T 160," + (12 - (idx % 3)) + " T 200," + (5 + (idx % 4))
    : "M 0," + (18 + (idx % 5)) + " Q 30," + (20 + (idx % 4)) + " 65," + (28 + (idx % 5)) + " T 120," + (26 + (idx % 4)) + " T 170," + (36 + (idx % 5)) + " T 200," + (40 - (idx % 3)),
  glowColor: s.up ? 'rgba(68, 222, 136, 0.25)' : 'rgba(244, 63, 94, 0.25)',
  borderColor: s.up ? 'rgba(68, 222, 136, 0.4)' : 'rgba(244, 63, 94, 0.4)',
  waveColor: s.up ? '#44DE88' : '#F43F5E',
  category: s.sector,
  high24h: s.val,
  low24h: s.val,
  volume24h: '$' + (2.5 + (idx * 0.35)).toFixed(1) + 'B',
  aiScore: s.score,
  aiRating: s.rating,
  description: s.desc,
}));

